function icon(name, size) {
  const s = size || 20;
  const d = ICONS[name] || "";
  return '<svg width="' + s + '" height="' + s + '" viewBox="0 0 20 20" fill="none" ' +
    'stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" ' +
    'aria-hidden="true">' + d + '</svg>';
}
